// One original field table for the fixed permanent contribution roots.
#pragma once
#include "growth_permanent_contributions.hpp"
#include <algorithm>
#include "growth_result_ref_fields.hpp"
#include "growth_capability_application_codec.hpp"
#include "resident/domains/actor_foundation/character_origin_codec_detail.hpp"
#include "resident/domains/tasks/work_execution/work_result_source_codec.hpp"
namespace hanmo::resident::growth_permanent_codec {
template<class C>Status text(C& c,const char* name,StableId& value){c.field(name,value);if(c.status().ok&&(value.empty()||value.size()>256))return c.reject("GrowthPermanentReferenceInvalid",name);return c.status();}
template<class C>Status source(C& c,PracticeSource& value){Integer tag=2;c.field("tag",tag);if(!c.status().ok)return c.status();if(tag!=2)return c.reject("GrowthPracticeSourceAdapterNotSelected");if(c.reading())value=WorkPracticeContribution{};auto& work=std::get<WorkPracticeContribution>(value);c.object("work_result_ref",[&](auto& x){return work_source_codec::result(x,work.result);});if(c.status().ok&&std::holds_alternative<LegacyAppeaseWork>(work.result))return c.reject("PracticeActualWorkResultRequired");std::size_t i=0;c.sequence("participation_refs",work.participation_refs,[&](auto& x,auto& id){text(x,"value",id);for(std::size_t n=0;x.status().ok&&n<i;++n)if(work.participation_refs[n]==id)return x.reject("PracticeWorkParticipationRepeated");++i;return x.status();});return c.status().ok&&work.participation_refs.empty()?c.reject("PracticeWorkParticipationMissing"):c.status();}
template<class C>Status skill(C& c,PracticeSkillReceipt& value){text(c,"skill_id",value.skill_id);c.field("xp_before",value.xp_before);c.field("requested_xp",value.requested_xp);c.field("actual_xp_gain",value.actual_xp_gain);c.field("xp_after",value.xp_after);if(c.status().ok&&(value.xp_before<0||value.xp_before>1200||value.requested_xp<10||value.requested_xp>40||value.actual_xp_gain!=std::min<Integer>(value.requested_xp,1200-value.xp_before)||value.xp_after!=value.xp_before+value.actual_xp_gain))return c.reject("PracticeAwardNetMismatch");return c.status();}
template<class C>Status award(C& c,PracticeAwardReceipt& value,bool capability_chain=false,GrowthContributionWireVersion wire=GrowthContributionWireVersion::original){text(c,"award_id",value.award_id);text(c,"actor_id",value.actor_id);c.object("practice_rule_ref",[&](auto& x){return character_origin_codec::rule(x,value.practice_rule_ref);});c.object("original_source",[&](auto& x){return source(x,value.original_source);});Integer role=static_cast<Integer>(value.contribution_role);c.field("contribution_role",role);if(c.status().ok&&role!=0)return c.reject("PracticeContributionRoleInvalid");if(c.reading()&&c.status().ok)value.contribution_role=PracticeContributionRole::work_leader;std::size_t i=0;c.sequence("skill_rows",value.skill_rows,[&](auto& x,auto& row){skill(x,row);for(std::size_t n=0;x.status().ok&&n<i;++n)if(value.skill_rows[n].skill_id==row.skill_id)return x.reject("PracticeSkillAwardRepeated");++i;return x.status();});c.object("applied_at",[&](auto& x){return character_origin_codec::at(x,value.applied_at,false);});c.object("original_fact_ref",[&](auto& x){return work_source_codec::source(x,value.original_fact_ref);});if(c.status().ok&&(value.skill_rows.empty()||value.skill_rows.size()>2||value.original_fact_ref.domain!="growth"||value.original_fact_ref.kind!="practice_award"||value.original_fact_ref.id!=value.award_id))return c.reject("PracticeAwardShapeInvalid");if(capability_chain){c.optional("capability_application",value.capability_application,[&](auto& x,auto& a){return growth_capability_codec::application(x,a,wire);});bool positive=false;for(const auto& row:value.skill_rows)positive=positive||row.actual_xp_gain>0;if(c.status().ok&&bool(value.capability_application)!=positive)return c.reject("PracticeCapabilityApplicationMismatch");}else if(value.capability_application)return c.reject("GrowthCapabilityPhysicalSelectionRequired");return c.status();}
template<class C>Status milestone(C& c,AttributeMilestone& value,bool capability_chain=false,GrowthContributionWireVersion wire=GrowthContributionWireVersion::original){text(c,"milestone_result_id",value.milestone_result_id);text(c,"actor_id",value.actor_id);text(c,"attribute_id",value.attribute_id);c.object("milestone_rule_ref",[&](auto& x){return character_origin_codec::rule(x,value.milestone_rule_ref);});c.object("original_outcome_ref",[&](auto& x){return source(x,value.original_outcome_ref);});text(c,"unique_milestone_id",value.unique_milestone_id);c.field("delta",value.delta);c.object("applied_at",[&](auto& x){return character_origin_codec::at(x,value.applied_at,false);});if(c.status().ok&&(value.delta!=1||(value.attribute_id!="administration"&&value.attribute_id!="charisma"&&value.attribute_id!="intellect"&&value.attribute_id!="leadership"&&value.attribute_id!="martial")))return c.reject("AttributeMilestoneShapeInvalid");if(capability_chain){c.optional("capability_application",value.capability_application,[&](auto& x,auto& a){return growth_capability_codec::application(x,a,wire);});if(c.status().ok&&!value.capability_application)return c.reject("MilestoneCapabilityApplicationRequired");}else if(value.capability_application)return c.reject("GrowthCapabilityPhysicalSelectionRequired");return c.status();}
template<class C>Status revision(C& c,GrowthCapabilityRevision& value,GrowthContributionWireVersion wire=GrowthContributionWireVersion::original){text(c,"actor_id",value.actor_id);c.field("revision",value.revision);c.object("last_change",[&](auto& x){return growth_capability_codec::change(x,value.last_change,wire);});if(c.status().ok&&value.revision<0)return c.reject("GrowthCapabilityRevisionInvalid");return c.status();}
}
